<?php require 'includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('SELECT * FROM admins WHERE email=?');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$u['admin_id'];$_SESSION['admin_name']=$u['name'];redirect('admin/dashboard.php');}flash('error','Invalid admin credentials.');}$title='Admin Login';$base='';$nav='<a href="login.php">Student Login</a>';include 'includes/header.php';?><div class="card form"><h2>Admin Login</h2><form method="post"><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><div class="actions"><button class="btn">Admin Login</button></div></form></div><?php include 'includes/footer.php';?>
